import {
  ModuleFeatureFlags,
  createModuleFeatureFlags,
} from "@/lib/modules/featureFlagGovernance";

/**
 * Module Manifest Registry
 *
 * Master Volume Governance:
 * - Vol 0: keeps audience-specific platform surfaces tied to one platform
 *   orientation.
 * - Vol I: preserves constitutional authority, role boundaries, and module
 *   isolation.
 * - Vol II: prevents module claims from becoming approvals, underwriting,
 *   notices, official reports, live external actions, or payment capture.
 * - Vol III: binds modules to the governed backend spine instead of direct
 *   record ownership.
 * - Vol III-B: provides manifest metadata for runtime, permission,
 *   classification, observability, and promotion checks.
 * - Vol IV: supports operator handoff, readiness, recovery, and deployment
 *   sequencing.
 * - Vol V: preserves content claims, replay, explainability, portability,
 *   controlled disclosure, and source-authority doctrine.
 * - Vol VI: declares each vertical surface as a portable governed module with
 *   explicit manifests, DTO boundaries, public surface posture, and source
 *   intelligence integration limits.
 *
 * Supplemental integration sources:
 * - Ares_Furlong_Module_Integration_Expansion_Requirements.docx
 * - Ares_Furlong_Platform_Integration_Architecture.docx
 * - Furlong_Volume_VI_Source_Intelligence_Integration_Master.pdf
 */

export type ModuleAudience =
  | "internal"
  | "borrower"
  | "lender"
  | "sponsor"
  | "public";

export type ModuleClaimsProfile =
  | "internal-governance"
  | "borrower-safe"
  | "lender-coordination"
  | "sponsor-coordination"
  | "public-safe"
  | "advisory-reporting"
  | "live-action-blocked";

export type ModuleManifest = {
  id: string;
  title: string;
  route: string;
  audience: ModuleAudience[];
  permissions: string[];
  dataDependencies: string[];
  requiredGovernance: string[];
  publicSurfaceAllowed: boolean;
  productionBlocked: boolean;
  claimsProfile: ModuleClaimsProfile;
  replayRequired: boolean;
  moduleNumber?: number;
  description: string;
  adjacentModules: string[];
  eventsPublished: string[];
  eventsConsumed: string[];
  featureFlags: ModuleFeatureFlags;
};

const internalFlags = createModuleFeatureFlags({
  module_enabled: true,
});

const translationFlags = createModuleFeatureFlags({
  module_enabled: true,
  public_surface_enabled: false,
});

const defaultGovernanceRequirements = [
  "CONST-DATA-001",
  "CANON-CLASS-001",
  "TECH-LEDGER-001",
  "TECH-REPLAY-001",
  "TECH-RBAC-001",
  "CANON-CLAIMS-001",
  "PROMOTION-GATE-001",
] as const;

function governanceForClaimsProfile(
  claimsProfile: ModuleClaimsProfile
): string[] {
  const requirements: string[] = [...defaultGovernanceRequirements];

  if (claimsProfile === "advisory-reporting") {
    requirements.push("CANON-EXPLAIN-001", "REPORT-ADVISORY-001");
  }

  if (claimsProfile === "borrower-safe") {
    requirements.push("BORROWER-PORTABILITY-001", "SURFACE-GOV-001");
  }

  if (
    claimsProfile === "lender-coordination" ||
    claimsProfile === "sponsor-coordination"
  ) {
    requirements.push("PARTNER-COORDINATION-001", "SURFACE-GOV-001");
  }

  if (claimsProfile === "live-action-blocked") {
    requirements.push("LIVE-ACTION-BLOCK-001", "CONNECTOR-GOV-001");
  }

  return Array.from(new Set(requirements));
}

function applyModuleConformance(
  manifest: Omit<ModuleManifest, "requiredGovernance">
): ModuleManifest {
  const requirements = governanceForClaimsProfile(manifest.claimsProfile);

  if (
    manifest.id.includes("revenue") ||
    manifest.dataDependencies.some((dependency) =>
      [
        "customer-revenue-opportunity-registry",
        "sellable-catalog-items",
        "program-graph-nodes",
        "marketplace-items",
        "operating-cost-signals",
        "market-signal-registry",
        "geo-suitability-profiles",
        "state-regulatory-records",
        "customer-type-eligibility-profiles",
        "advisory-fusion-results",
      ].includes(dependency)
    )
  ) {
    requirements.push(
      "REVENUE-INTEL-001",
      "SELLABLE-CATALOG-001",
      "PROGRAM-GRAPH-001",
      "MARKETPLACE-INTEL-001",
      "OPERATING-COST-GOV-001",
      "MARKET-SIGNAL-001",
      "GEOSPATIAL-GOV-001",
      "STATE-REGISTRY-001",
      "CUSTOMER-TYPE-ELIGIBILITY-001",
      "DATA-FUSION-001"
    );
  }

  if (
    manifest.id.includes("environmental") ||
    manifest.dataDependencies.some((dependency) =>
      [
        "environmental-compliance-records",
        "borrower-protection-fee-controls",
        "provider-license-verification",
      ].includes(dependency)
    )
  ) {
    requirements.push(
      "ROLE-ARCH-001",
      "REG-NEPA-001",
      "USDA-ENV-001",
      "OPS-BORROWER-JOURNEY-001",
      "CANON-ECON-001",
      "CANON-SOVEREIGNTY-001"
    );
  }

  return {
    ...manifest,
    requiredGovernance: Array.from(new Set(requirements)),
  };
}

