export const moduleManifests: ModuleManifest[] = rawModuleManifests.map(
  applyModuleConformance
);

export function getModuleManifest(id: string): ModuleManifest | null {
  return moduleManifests.find((manifest) => manifest.id === id) ?? null;
}

export function moduleManifestsByAudience(
  audience: ModuleAudience
): ModuleManifest[] {
  return moduleManifests.filter((manifest) =>
    manifest.audience.includes(audience)
  );
}

export function publicSurfaceManifests(): ModuleManifest[] {
  return moduleManifests.filter(
    (manifest) =>
      manifest.publicSurfaceAllowed && !manifest.audience.includes("internal")
  );
}
